def simulate(grid, dirs, step=1, stop_nonbg=True, stop_edge=True, stop_seed=True):
    H,W=grid.shape; out=grid.copy(); bg=int(np.unique(out)[0]); seen=set()
    for sr,sc in np.argwhere(grid!=bg):
        for dr,dc in dirs:
            r,c=sr+dr,sc+dc
            while True:
                if not (0<=r<H and 0<=c<W): break
                val=out[r,c]
                if stop_nonbg and val!=bg: break
                if stop_seed and val!=bg: break
                if stop_edge: pass  # covered by bounds above
                out[r,c]=5; seen.add((r,c)); r+=dr;c+=dc
                if step>1:
                    rr,cc=r,c
                    while True:
                        if not (0<=rr<H and 0<=cc<W): break
                        if stop_nonbg and out[rr,cc]!=bg: break
                        if stop_seed and out[rr,cc]!=bg: break
                        out[rr,cc]=5; seen.add((rr,cc)); rr+=dr;cc+=dc
                        if step<=1: break
    return out,seen

